arguments.argument:
// 記憶モード
if( memory_mode == 1 ){
  var fartid;

  // 放屁中ならば、エフェクトの種類を記録
  if( global.farting_time != 0 ){
    fartid = global.current_mode * 100;
    fartid += global.current_pattern;

    ds_map_add(map_step_to_fartid[memory_area], play_count, fartid);
  }

  play_count += 1;

  // 記憶カウントが終了した場合
  if( play_count >= global.memory_time_max*room_speed ){
    play_count = 0;
    memory_mode = 0;
  }
}
// 再生モード
if( memory_mode == 2 ){
  var fartid;

  if( ds_map_exists(map_step_to_fartid[memory_area], play_count) ){
    fartid = ds_map_find_value(map_step_to_fartid[memory_area], play_count);

    global.current_mode = floor(fartid/100);
    global.current_pattern = fartid mod 100;

    keyboard_key_press(vk_space);
  }else{
    keyboard_key_release(vk_space);
  }

  play_count += 1;

  // 再生カウントが終了した場合
  if( play_count >= global.memory_time_max*room_speed ){
    play_count = 0;
    //memory_mode = 0;
    keyboard_key_release(vk_space);
  }
}

// Ctrl+数字キーで再生
if( memory_mode == 0 && keyboard_check(vk_control) ){
  var i;
  for(i=0; i<min(10, MEMORY_AREA_MAX); i+=1){
    if( keyboard_check_pressed(ord(string(i))) ){
      memory_area = i;
      memory_mode = 2;
      break;      
    }
  }
}
